window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[67]={"id":"067","numero":67,"titre":"Troubles envahissants du développement","objectifs":[{"id":"67-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la définition et la sémiologie des troubles du spectre de l’autisme","contenu":"<p>Le <span class=\"kw-def\">trouble du spectre de l’autisme (TSA)</span> est un <strong>trouble d’origine neurodéveloppementale</strong> dont <span class=\"kw-clinique\">les</span> signes psychopathologiques principaux se manifestent par :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">perturbations dans l’interaction et la communication sociale</span> ;</li>\n        <li><span class=\"kw-clinique\">caractère restreint et répétitif</span> des comportements, des intérêts ou des activités.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Repères épidémiologiques</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Prévalence</span></td><td><span class=\"kw-chiffre\">1%</span></td></tr>\n          <tr><td>Sex-ratio</td><td>Prédominance masculine <span class=\"kw-chiffre\">4G / 1F</span></td></tr>\n          <tr><td>Âge d’apparition</td><td>Petite enfance, <span class=\"kw-chiffre\">&lt; 3 ans</span> (certains symptômes très précoces, d’autres plus tardifs ; le diagnostic se base sur la symptomatologie actuelle <strong>+</strong> la trajectoire développementale)</td></tr>\n          <tr><td>Sévérité</td><td>Variable, fonction des <span class=\"kw-def\">comorbidités</span> : déficience intellectuelle (<span class=\"kw-chiffre\">50%</span>), altération du langage, etc.</td></tr>\n          <tr><td>Filière</td><td>Tout praticien doit savoir repérer <span class=\"kw-clinique\">les</span> signes d’alerte dès les 1ères phases du développement et dès qu’un parent exprime une inquiétude → orienter vers <span class=\"kw-ttt\">Centre Ressources Autisme (CRA)</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Anomalies de la communication et des interactions sociales</h4>\n      <table >\n        <thead><tr><th>Axe</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Déficit de réciprocité</strong></td>\n            <td>\n              <strong>Sourires-réponses :</strong> absence / rareté (l’enfant ne sourit pas en réponse aux parents)<br>\n              <strong>Attention conjointe :</strong> pauvreté ; <span class=\"kw-clinique\">ne répond pas quand on l’appelle alors qu’il n’est pas sourd</span><br>\n              <strong>Échanges :</strong> conversations centrées sur ses propres intérêts<br>\n              <strong>Pragmatique du langage :</strong> difficulté d’accès à l’implicite et au langage figuré\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Anomalie du <span class=\"kw-def\">contact</span></strong></td>\n            <td>\n              <strong>Communication non verbale :</strong> peu d’expressions faciales, gestuelle pauvre<br>\n              <strong><span class=\"kw-def\">Contact</span> oculaire :</strong> absence / rareté / fluctuant<br>\n              <strong>Gestes instrumentaux à valeur sociale :</strong> ne fait pas oui/non de la tête, ni « coucou / au revoir »<br>\n              <strong>Pointage :</strong> rareté du proto-impératif (montrer pour obtenir) <em>et</em> du proto-déclaratif (montrer pour attirer l’attention sur un objet)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Anomalie sociale</strong></td>\n            <td>\n              <strong>Jeu :</strong> absence / anomalie (pas de jeux sociaux réciproques, pas de faire-semblant)<br>\n              <strong>Conventions sociales :</strong> maladresse, <span class=\"kw-def\">isolement</span> relationnel<br>\n              <strong>Motivation sociale :</strong> peu d’intérêt pour <span class=\"kw-clinique\">les</span> pairs\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Caractère restreint et répétitif des comportements / intérêts / activités</h4>\n      <table >\n        <thead><tr><th>Dimension</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Comportements répétitifs<br>et stéréotypés</strong></td>\n            <td>\n              <strong>Stéréotypies motrices :</strong> mouvements répétitifs du tronc, de la tête, des membres supérieurs (<span class=\"kw-clinique\">flapping</span>) ; risque d’<span class=\"kw-alerte\">automutilation</span><br>\n              <strong>Utilisation répétitive des objets :</strong> <span class=\"kw-clinique\">alignement</span> des jouets, activité de <span class=\"kw-clinique\">rotation</span><br>\n              <strong>Stéréotypies verbales</strong> ; <strong>écholalies</strong> immédiates ou différées ; <strong>langage idiosyncrasique</strong> (langage propre, stable)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Routines inflexibles</strong></td>\n            <td>\n              <strong>Adhésion inflexible</strong> aux routines même mineures (même itinéraire, même nourriture, même couleur de vêtements)<br>\n              <strong>Rituels</strong> verbaux (questionnements répétitifs) ou non verbaux (déambulations)<br>\n              <strong><span class=\"kw-ci\">Intolérance</span> au changement</strong> (besoin d’immuabilité) : <span class=\"kw-alerte\">détresse</span> face à un changement même mineur (tapisserie, emballage…)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Intérêts restreints<br>et fixes</strong></td>\n            <td>\n              <strong>Attachement idiosyncratique</strong> à des objets insolites (casserole, caillou, t<span class=\"kw-chiffre\">ige</span> métallique…)<br>\n              <strong>Peurs inhabituelles</strong> au regard de l’âge (rideau soulevé par le vent, voix chantée, coupe de cheveux…)<br>\n              <strong>Intérêts circonscrits et persévérants</strong> (chiffres, lettres, lignes de métro, système solaire, coléoptères…)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Particularités sensorielles</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Hypo</span> ou <span class=\"kw-clinique\">hyperréactivité</span> à certaines stimulations sensorielles ; intérêt inhabituel pour <span class=\"kw-clinique\">les</span> aspects sensoriels (apparente indifférence à la douleur / température, sensibilité excessive aux bruits, comportements de flairage, fascination pour certains stimuli lumineux…)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Signes d’alerte par tranche d’âge</h4>\n      <table >\n        <thead><tr><th>Tranche</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">0-6 mois</span></strong></td>\n            <td>Nourrisson trop calme/indifférent <em>ou</em> trop agité ; <span class=\"kw-clinique\">absence de sourire-réponse</span> ; <span class=\"kw-clinique\">pas de regard</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">6-12 mois</span></strong></td>\n            <td>Activités stéréotypées verbales ou motrices ; <strong>pas de peur de l’étranger</strong>, aréactivité au bruit, désintérêt pour l’environnement</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">12-24 mois</span></strong></td>\n            <td>Retard de langage — env. <span class=\"kw-chiffre\">1/3</span> des enfants présentent une <span class=\"kw-alerte\">stagnation ou régression</span> du développement socio-communicatif (langage oral + interactions sociales) ; retard global des acquisitions ; automutilation, absence de jeu, comportements bizarres</td>\n          </tr>\n          <tr>\n            <td><strong>Enfant</strong></td>\n            <td>Anomalies de la communication / interactions sociales <strong>+</strong> caractère restreint et répétitif des comportements et intérêts</td>\n          </tr>\n          <tr>\n            <td><strong>Adulte</strong> (TSA sans atteinte du langage ni handicap intellectuel)</td>\n            <td>\n              <strong>Stratégies de compensation</strong> souvent développées ; peuvent contrôler <span class=\"kw-clinique\">les</span> comportements répétitifs en public.<br>\n              Manifestations surtout en situations sociales complexes : défaut d’intégration de l’attitude corporelle, prosodie / débit / niveau sonore / hauteur de voix inhabituels.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Repère pédagogique.</strong> Le diagnostic du TSA reste <span class=\"kw-def\">clinique</span> ; la sémiologie tourne autour de <strong>deux dyades</strong> à connaître par cœur — (1) communication + interactions sociales altérées, (2) comportements / intérêts restreints et répétitifs. C’est ce qu’on retrouve dans <span class=\"kw-clinique\">les</span> critères <span class=\"kw-def\">DSM-5</span> (objectif suivant).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 68 — Troubles du comportement de l'ado</em></p>","frequence":2},{"id":"67-2","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques DSM-5","contenu":"<p>Le diagnostic de TSA est <span class=\"kw-def\">clinique</span>, fondé sur <span class=\"kw-clinique\">les</span> critères <span class=\"kw-def\">DSM-5</span>. Il s’appuie sur 4 piliers à connaître :</p>\n      <ul>\n        <li><strong>Anomalies de la communication et des interactions sociales</strong> ;</li>\n        <li><strong>Caractère restreint et répétitif</strong> des comportements, des intérêts ou des activités ;</li>\n        <li><strong>Manifestations dès <span class=\"kw-clinique\">les</span> étapes précoces du développement</strong> ;</li>\n        <li><strong>Retentissement significatif</strong> (fonctionnel, scolaire, social, familial).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Comment recueillir l’information ?</h4>\n      <table >\n        <thead><tr><th>Source</th><th>Outils</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td><span class=\"kw-clinique\">Multidisciplinaire</span> — développement de l’enfant : langage, communication, intelligence, motricité.</td>\n          </tr>\n          <tr>\n            <td><strong>Observation de l’enfant</strong></td>\n            <td><span class=\"kw-ttt\">ADOS</span> — Autism Diagnostic <strong>Observation</strong> Schedule (observation semi-structurée de la symptomatologie).</td>\n          </tr>\n          <tr>\n            <td><strong>Entretien parental</strong></td>\n            <td><span class=\"kw-ttt\">ADI-R</span> — Autism Diagnostic <strong>Interview</strong>-Revised (semi-structuré ; symptomatologie <em>actuelle</em> + histoire développementale).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Démarche diagnostique complète</h4>\n      <table >\n        <thead><tr><th>Volet</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic positif</span></strong></td>\n            <td>\n              <strong>Outils standardisés :</strong> <span class=\"kw-ttt\">ADI-R</span> + <span class=\"kw-ttt\">ADOS</span><br>\n              <strong>Examen multidisciplinaire</strong> systématique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Enquête étiologique</strong></td>\n            <td><strong>Anamnèse + clinique + questionnaires / entretiens</strong> ; <span class=\"kw-ttt\">± paracliniques</span> ; <span class=\"kw-ttt\">± consultations spécialisées</span></td>\n          </tr>\n          <tr>\n            <td><strong>Formes syndromiques</strong><br>(recherche de cause sous-jacente)</td>\n            <td>\n              <strong>Bilan neurologique</strong> ;<br>\n              <strong>Bilan <span class=\"kw-etio\">génétique</span></strong> ;<br>\n              <strong>Bilan métabolique</strong> ;<br>\n              <strong><span class=\"kw-imagerie\">IRM</span> cérébrale</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Différentiel + <span class=\"kw-def\">comorbidités</span></strong></td>\n            <td>\n              <strong>Évaluation cognitive :</strong> QI + comportement adaptatif ;<br>\n              <strong>Bilan orthophonique</strong> (troubles du langage) ;<br>\n              <strong>Bilan psychomoteur</strong> (coordination, développement moteur)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Différentiel spécifique</strong></td>\n            <td><span class=\"kw-ttt\">Audiogramme + PEA</span> — éliminer une <span class=\"kw-clinique\">surdité</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Comorbidités</span> neuro</strong></td>\n            <td><span class=\"kw-ttt\">EEG de veille et de sommeil</span> (<span class=\"kw-etio\">épilepsie</span>, troubles du sommeil)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Diagnostics différentiels</h4>\n      <ul>\n        <li><strong>Enfant :</strong> autres troubles neurodéveloppementaux, <span class=\"kw-clinique\">surdité</span>, <span class=\"kw-etio\">schizophrénie</span> à début précoce.</li>\n        <li><strong>Adulte :</strong> autres troubles du neurodéveloppement, trouble d’anxiété sociale, TOC, troubles de la personnalité, troubles liés à des traumatismes / facteurs de stress, <span class=\"kw-etio\">schizophrénie</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Comorbidités</span> du TSA</h4>\n      <table >\n        <thead><tr><th>Famille</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Non psychiatriques</strong></td>\n            <td><span class=\"kw-etio\">Épilepsie</span> <span class=\"kw-chiffre\">20%</span> ; <span class=\"kw-clinique\">troubles du sommeil</span></td>\n          </tr>\n          <tr>\n            <td><strong>Neurodéveloppementales</strong></td>\n            <td>\n              <strong>Trouble du développement intellectuel</strong> <span class=\"kw-chiffre\">40%</span> ;<br>\n              <strong>TDAH</strong> <span class=\"kw-chiffre\">30-40%</span> ;<br>\n              <strong>Troubles de l’acquisition de la parole et du langage</strong> (<span class=\"kw-chiffre\">20%</span> n’ont pas de langage verbal) ;<br>\n              <strong>Tics</strong>, troubles de la coordination motrice, des apprentissages\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Psychiatriques</strong></td>\n            <td>\n              Troubles <span class=\"kw-clinique\">anxieux</span> (phobies spécifiques, phobie sociale, TAG) ;<br>\n              Symptômes obsessionnels compulsifs, <span class=\"kw-clinique\">EDC</span> ;<br>\n              <span class=\"kw-clinique\">Syndromes catatoniques</span> = perturbation grave de l’organisation psychomotrice\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres (adulte)</strong></td>\n            <td><span class=\"kw-etio\">Schizophrénie</span> ; trouble de la personnalité</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> ADI-R = <em>Interview</em> des parents ; ADOS = <em>Observation</em> de l’enfant. Le couple <span class=\"kw-ttt\">ADI-R + ADOS</span> est la <strong>référence diagnostique standardisée</strong> et un grand classique de l’EDN — à ne pas confondre avec ADHD-RS / CONNERS qui sont <span class=\"kw-clinique\">les</span> outils du TDAH (objectifs suivants).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 121 — Handicap psychique</em></p>","frequence":5},{"id":"67-3","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge","contenu":"<p>La prise en charge du TSA est <span class=\"kw-def\">multidisciplinaire</span>, <strong>précoce</strong> et <strong>centrée sur la scolarisation + <span class=\"kw-clinique\">les</span> interventions non médicamenteuses</strong>. <span class=\"kw-alerte\">Il n’existe aucun traitement curatif du TSA</span> — les médicaments ciblent les <span class=\"kw-def\">comorbidités</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Scolarisation selon l’intensité</h4>\n      <table >\n        <thead>\n          <tr>\n            <th>Intensité</th>\n            <th><span class=\"kw-def\">Comorbidité</span></th>\n            <th>Retentissement</th>\n            <th>Scolarisation</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Légère</strong></td>\n            <td>Non</td>\n            <td>Léger</td>\n            <td>Milieu ordinaire (± <span class=\"kw-ttt\">AVS/AESH</span> via <span class=\"kw-ttt\">PPS-MDPH</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Légère</strong></td>\n            <td>Trouble neurodéveloppemental associé</td>\n            <td>Léger ou modéré</td>\n            <td>\n              <strong>UEMA</strong> (Unité d’Enseignement Maternelle Autisme — école maternelle) ;<br>\n              <strong>ULIS</strong> ou <strong>UEEA</strong> (UE Élémentaire Autisme) — à partir du primaire ;<br>\n              Appui d’un <strong>SESSAD</strong> utile pour favoriser l’inclusion en milieu scolaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Modérée à sévère</strong></td>\n            <td>Trouble neurodéveloppemental associé</td>\n            <td><span class=\"kw-alerte\">Modéré ou sévère</span></td>\n            <td><strong>Institut médico-éducatif (IME)</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Vie professionnelle de l’adulte</h4>\n      <ul>\n        <li>Aménagements en matière de <strong>communication, environnement de travail et gestion du stress</strong> ;</li>\n        <li>Employeurs : rôle clé pour favoriser un milieu de travail inclusif ;</li>\n        <li>Études supérieures : aménagements des cours, examens et stages ; soutien via la médecine universitaire ou des programmes spécifiques (ex. <strong>Atypie-Friendly</strong>).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Traitements non pharmacologiques</h4>\n      <table >\n        <thead><tr><th>Axe</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Programmes développementaux</strong></td>\n            <td>\n              <strong>Objectif :</strong> <span class=\"kw-clinique\">relancer la trajectoire développementale</span><br>\n              <strong>Base :</strong> connaissances du développement cérébral et fonctionnel<br>\n              <strong>Comment :</strong> activation des systèmes de synchronisation socio-émotionnelle\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Programmes comportementaux</strong></td>\n            <td>\n              <strong>Objectif :</strong> favoriser l’apprentissage des comportements utiles à la communication et adaptés socialement<br>\n              <strong>Base :</strong> théories de l’apprentissage — <span class=\"kw-clinique\">stimulation, répétition, renforcement positif</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Psychothérapie</strong></td>\n            <td>\n              <span class=\"kw-ttt\">TCC en groupe</span> pour la rééducation des habiletés sociales :<br>\n              améliorer la compréhension des conventions sociales et <span class=\"kw-clinique\">les</span> compétences en interactions sociales\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Rééducations orthophoniques</strong></td>\n            <td>\n              <strong>Indications :</strong>\n              <ul style=\"margin:6px 0 0 18px;\">\n                <li>difficultés en <strong>pragmatique du langage</strong> (implicite, langage figuré) ;</li>\n                <li>performances faibles en <strong>communication verbale</strong> (patients non verbaux) — combinent rééducation classique du langage oral + rééducations spécialisées (pictogrammes : communication par images, famille formée).</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Social</strong></td>\n            <td>Associations de parents = partenaires indispensables (ex. <strong>Autisme France</strong>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Traitements pharmacologiques</h4>\n      <div class=\"callout callout-warn\">\n        <strong>Règle absolue.</strong> <span class=\"kw-alerte\">Aucun traitement curatif du TSA</span> ❌. <span class=\"kw-clinique\">Les</span> médicaments traitent uniquement les <strong>symptômes sévères</strong> et les <strong><span class=\"kw-def\">comorbidités</span></strong>.\n      </div>\n      <table >\n        <thead><tr><th>Cible</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptômes obsessionnels et compulsifs sévères</strong></td>\n            <td><span class=\"kw-ttt\">ISRS</span></td>\n          </tr>\n          <tr>\n            <td><strong>Irritabilité, hétéro- ou auto-agressivité sévère</strong></td>\n            <td>\n              <strong><span class=\"kw-chiffre\">1ère intention</span> :</strong> interventions <span class=\"kw-clinique\">comportementales</span><br>\n              <strong>2ème intention :</strong> <span class=\"kw-ttt\">antipsychotique de 2ème génération</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Comorbidité</span> EDC</strong></td>\n            <td><span class=\"kw-ttt\">ISRS</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Comorbidité</span> TDAH</strong></td>\n            <td><span class=\"kw-ttt\">Méthylphénidate</span> associé</td>\n          </tr>\n          <tr>\n            <td><strong>Troubles du sommeil</strong></td>\n            <td><span class=\"kw-ttt\">Mélatonine</span> — <span class=\"kw-ci\">pas de benzodiazépines</span> ⚠️</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 121 — Handicap psychique</em></p>","frequence":0},{"id":"67-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition et la sémiologie d’un trouble déficit de l’attention hyperactivité (TDAH)","contenu":"<p>Le <span class=\"kw-def\">TDAH</span> (trouble déficit de l’attention avec ou sans hyperactivité) se caractérise par une <strong>inattention</strong> et/ou une <strong>hyperactivité/impulsivité</strong> plus importantes que ce qui est attendu pour l’âge. <span class=\"kw-clinique\">Les</span> symptômes débutent dans l’<span class=\"kw-clinique\">enfance</span>, sont <strong>durables/persistants</strong> et entraînent un <strong>retentissement</strong>. L’expression varie selon le contexte.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Repères épidémiologiques</h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Prévalence</span></td><td><span class=\"kw-chiffre\">5%</span> des enfants en âge scolaire</td></tr>\n          <tr><td>Sex-ratio</td><td>Prédominance masculine <span class=\"kw-chiffre\">3G / 1F</span></td></tr>\n          <tr>\n            <td>Manifestations selon l’âge</td>\n            <td>\n              <strong>Instabilité motrice + impulsivité :</strong> dès l’<span class=\"kw-clinique\">âge de la marche</span> (difficile à distinguer de l’agitation normale des jeunes enfants) ;<br>\n              <strong>Syndrome d’inattention :</strong> plus visible en <span class=\"kw-clinique\">école élémentaire</span> quand un effort de concentration est demandé (diagnostic souvent tardif si l’inattention prédomine)\n            </td>\n          </tr>\n          <tr>\n            <td>Manifestations selon le sexe</td>\n            <td>Inattention prédominante chez la <strong>fille</strong> (hyperactivité parfois absente) → <span class=\"kw-alerte\">diagnostic souvent tardif</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Évolution</span> dans le temps</td>\n            <td>\n              <strong>Hyperactivité motrice :</strong> s’atténue ou change de forme (sensation intérieure d’impatience, besoin de manipuler des objets) ;<br>\n              <strong>Impulsivité et inattention :</strong> restent souvent problématiques ;<br>\n              Persistance à l’âge adulte avec retentissement pour <span class=\"kw-chiffre\">2/3</span> des patients (chez l’adulte, le diagnostic requiert <em>moins</em> de critères que chez l’enfant)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie — 3 syndromes à connaître</h4>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Inattention</strong></td>\n            <td>\n              <ul style=\"margin:0 0 0 18px;\">\n                <li>Difficultés à se concentrer et à <strong>maintenir</strong> la concentration (fautes d’étourderie dans <span class=\"kw-clinique\">les</span> devoirs) ;</li>\n                <li><strong><span class=\"kw-clinique\">Distractibilité</span></strong> par distracteurs internes (pensées) ou externes (stimuli) ;</li>\n                <li>Difficultés à comprendre et suivre <strong>règles et consignes</strong> ;</li>\n                <li>Difficultés d’<strong>organisation</strong> liées à un défaut de planification et de mémoire de travail (= fonctions exécutives) — ex. cartable / agenda ;</li>\n                <li><strong>Oublis</strong> ou pertes d’objets (jouets, habits) ;</li>\n                <li><strong>Procrastination</strong> systématique ;</li>\n                <li><strong>Lenteur d’exécution</strong> ;</li>\n                <li><strong>Évitement</strong> et manque de motivation pour <span class=\"kw-clinique\">les</span> tâches demandant un effort cognitif durable (travail scolaire).</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hyperactivité</strong></td>\n            <td>\n              Activité <strong>excessive, désordonnée, mal contrôlée</strong>, peu productive ni efficace → <span class=\"kw-clinique\">instabilité motrice</span> :\n              <ul style=\"margin:6px 0 0 18px;\">\n                <li>ne parvient pas à rester assis, court partout ;</li>\n                <li>hyperactivité présente dans <strong>quasiment tous <span class=\"kw-clinique\">les</span> domaines de vie</strong> (familial, social, extra-scolaire) ;</li>\n                <li>« bouge sans arrêt, comme une pile électrique, monté sur ressort, ne s’arrête jamais, remue <span class=\"kw-clinique\">les</span> jambes même assis ».</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Impulsivité</strong></td>\n            <td>\n              Faire ou dire quelque chose de façon impérieuse, <strong>sans pouvoir différer</strong>, sans anticiper <span class=\"kw-clinique\">les</span> conséquences :\n              <ul style=\"margin:6px 0 0 18px;\">\n                <li><strong><span class=\"kw-clinique\">Précipitation</span></strong> (répondre sans attendre la fin de la question) ;</li>\n                <li><strong>Prises de risques</strong> (ne regarde pas avant de traverser) ;</li>\n                <li><strong>Incapacité à attendre son tour</strong> (jeux, tours de parole).</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Comorbidités</span> et complications</h4>\n      <table >\n        <thead><tr><th>Domaine</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Comorbidités</span></strong></td>\n            <td>\n              Troubles des <strong>apprentissages</strong> (<span class=\"kw-chiffre\">50-80%</span>) ;<br>\n              Troubles du <strong>comportement</strong> (TOP / TC <span class=\"kw-chiffre\">&gt; 50%</span>) ;<br>\n              <span class=\"kw-chiffre\">≥ 80%</span> des TDAH ont une <span class=\"kw-def\">comorbidité</span> psychiatrique — symptômes <strong><span class=\"kw-def\">transnosographiques</span></strong> (inattention / hyperactivité / impulsivité retrouvées dans diverses pathologies) qui rendent <span class=\"kw-clinique\">floue la frontière comorbidité / diagnostic différentiel</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Sociales</strong></td>\n            <td>Conflits intrafamiliaux, difficultés d’intégration sociale, harcèlement, maltraitance</td>\n          </tr>\n          <tr>\n            <td><strong>Scolaires</strong></td>\n            <td>Difficultés d’apprentissage, échec scolaire, déscolarisation</td>\n          </tr>\n          <tr>\n            <td><strong>Professionnelles</strong></td>\n            <td>Difficulté d’intégration professionnelle, chômage, marginalisation</td>\n          </tr>\n          <tr>\n            <td><strong>Judiciaires</strong></td>\n            <td>Délinquance, criminalisation, conséquences judiciaires</td>\n          </tr>\n          <tr>\n            <td><strong>Organiques</strong></td>\n            <td>Liées aux comportements à risque (ex. traumatismes orthopédiques)</td>\n          </tr>\n          <tr>\n            <td><strong>Psychiatriques</strong></td>\n            <td>Troubles anxieux, troubles de l’humeur, troubles addictifs, troubles du sommeil</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Triade pédagogique à retenir.</strong> <span class=\"kw-def\">Inattention + Hyperactivité + Impulsivité</span> — avec une expression variable selon le sexe (fille = inattention prédominante, diagnostic souvent tardif) et selon l’âge (hyperactivité prédominante en préscolaire, inattention en élémentaire).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 68 — Troubles du comportement de l'ado · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p>","frequence":4},{"id":"67-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques selon l’âge","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> du TDAH est <span class=\"kw-def\">clinique</span>, fondé sur une <strong>observation clinique structurée</strong> qui recueille l’histoire développementale, la symptomatologie actuelle, le retentissement, la durée et <span class=\"kw-clinique\">les</span> arguments supplémentaires.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Critères diagnostiques</span> cliniques</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge de début</strong></td>\n            <td>Trouble débuté <span class=\"kw-chiffre\">&lt; 12 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Informations à recueillir</strong></td>\n            <td>\n              <strong>Histoire développementale</strong> du patient ;<br>\n              <strong>Symptomatologie actuelle</strong> (nombre suffisant de symptômes requis) — <strong>3 présentations cliniques</strong> :\n              <ul style=\"margin:6px 0 0 18px;\">\n                <li><strong>Inattentive prédominante</strong> — diagnostic <span class=\"kw-alerte\">souvent tardif</span> ;</li>\n                <li><strong>Hyperactive / impulsive prédominante</strong> — surtout en période <span class=\"kw-clinique\">préscolaire</span> ;</li>\n                <li><strong>Combinée</strong> — <span class=\"kw-clinique\">les</span> deux dimensions cliniques au premier plan.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Retentissement</strong></td>\n            <td>\n              Dans <span class=\"kw-chiffre\">≥ 2 domaines</span> de vie parmi :\n              <ul style=\"margin:6px 0 0 18px;\">\n                <li><strong>familial</strong> restreint et élargi ;</li>\n                <li><strong>scolaire</strong> ;</li>\n                <li><strong>extra-scolaire</strong> ;</li>\n                <li><strong>amical</strong>.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td><span class=\"kw-chiffre\">&gt; 6 mois</span></td>\n          </tr>\n          <tr>\n            <td><strong>Arguments supplémentaires</strong><br>(pas de valeur diagnostique propre — peu spécifiques)</td>\n            <td>\n              <strong>Questionnaires :</strong> <span class=\"kw-ttt\">ADHD-Rating Scale</span>, <span class=\"kw-ttt\">CONNERS</span> <em>(à ne pas confondre avec ADI-R / ADOS du TSA)</em> ;<br>\n              <strong>Tests neuropsychologiques :</strong> tests d’attention, tests de QI (performances souvent altérées, mais non spécifiques)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Diagnostics différentiels<br>(souvent aussi <span class=\"kw-def\">comorbidités</span> du TDAH)</h4>\n      <table >\n        <thead><tr><th>Famille</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Troubles du neurodéveloppement</strong></td>\n            <td>\n              <strong>Troubles des acquisitions / apprentissages</strong> : présents chez <span class=\"kw-chiffre\">50-80%</span> des enfants TDAH ;<br>\n              Handicap intellectuel ; <span class=\"kw-etio\">trouble du spectre de l’autisme</span> ; tics\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Troubles du comportement</strong></td>\n            <td>Associés dans <span class=\"kw-chiffre\">80%</span> des cas pour <strong>TOP</strong> ; <span class=\"kw-chiffre\">25%</span> pour <strong>TC</strong> → mauvais <span class=\"kw-def\">pronostic</span></td>\n          </tr>\n          <tr>\n            <td><strong>Troubles du sommeil</strong></td>\n            <td>Un <span class=\"kw-etio\">SAHOS</span> peut <strong>causer</strong> un TDAH (conséquences neuropsychiques)</td>\n          </tr>\n          <tr>\n            <td><strong>Autres troubles psychiatriques</strong></td>\n            <td>Trouble <span class=\"kw-clinique\">anxieux</span> (chez <span class=\"kw-chiffre\">33%</span> des enfants TDAH) ; troubles de l’humeur ; TOC ; troubles addictifs</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique EDN.</strong> Ne pas confondre <span class=\"kw-clinique\">les</span> outils diagnostiques :<br>\n        TSA → <span class=\"kw-ttt\">ADI-R</span> (Interview parents) + <span class=\"kw-ttt\">ADOS</span> (Observation enfant).<br>\n        TDAH → <span class=\"kw-ttt\">ADHD-RS</span> + <span class=\"kw-ttt\">CONNERS</span>. Et <strong>aucun</strong> de ces outils n’est diagnostique <em>à lui seul</em> — le diagnostic reste clinique.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 68 — Troubles du comportement de l'ado · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p>","frequence":0},{"id":"67-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes des traitements psychosociaux et médicamenteux","contenu":"<p>La prise en charge du TDAH est <span class=\"kw-def\">multidisciplinaire</span>, hiérarchisée : <strong>aménagements scolaires + psychothérapie en <span class=\"kw-chiffre\">1ère intention</span></strong>, traitement <span class=\"kw-etio\">médicamenteux</span> (<span class=\"kw-ttt\">méthylphénidate</span>) si insuffisance des mesures non pharmacologiques chez l’enfant <span class=\"kw-chiffre\">≥ 6 ans</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Scolarisation</h4>\n      <table >\n        <thead><tr><th>Niveau</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Conseils simples</strong><br>(distractibilité &amp; fat<span class=\"kw-chiffre\">iga</span>bilité cognitive)</td>\n            <td>\n              <ul style=\"margin:0 0 0 18px;\">\n                <li>Placer l’enfant <strong>devant</strong>, près du tableau, <strong>loin d’une fenêtre, seul</strong> ;</li>\n                <li>Fractionner <span class=\"kw-clinique\">les</span> exercices, <strong>1 consigne à la fois</strong> ;</li>\n                <li>Faire des <strong>pauses</strong>, alléger l’emploi du temps.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Aménagements formalisés</strong></td>\n            <td>\n              <span class=\"kw-ttt\">PAP</span> (Plan d’Accompagnement Personnalisé) — <span class=\"kw-clinique\">sans reconnaissance MDPH</span> ;<br>\n              <span class=\"kw-ttt\">PPS</span> (Projet Personnalisé de Scolarisation) — <span class=\"kw-clinique\">enfant reconnu handicapé par la MDPH</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>AVS / AESH</strong></td>\n            <td>Aide humaine pour le travail scolaire (utile en <span class=\"kw-bio\">complément</span> du PAP / <span class=\"kw-def\">PPS</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Psychothérapie</h4>\n      <table >\n        <thead><tr><th>Approche</th><th>Précision</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Éducation thérapeutique</span> adaptée</strong></td>\n            <td><span class=\"kw-clinique\">Systématique</span>, en groupe ou individuel</td>\n          </tr>\n          <tr>\n            <td><strong>Programmes de renforcement des habiletés parentales</strong></td>\n            <td>Utiles si retentissement important ou <span class=\"kw-def\">comorbidité</span> de trouble du comportement (basés sur stratégies cognitivo-comportementales + théories de l’apprentissage et de l’attachement)</td>\n          </tr>\n          <tr>\n            <td><strong>TCC individuelle ou de groupe</strong></td>\n            <td>Ciblant <span class=\"kw-clinique\">les</span> dimensions associées au TDAH (estime de soi, affirmation de soi, compétences sociales)</td>\n          </tr>\n          <tr>\n            <td><strong>Programmes de <span class=\"kw-ttt\">remédiation cognitive</span></strong></td>\n            <td>Exercices ludiques d’attention, d’inhibition de l’impulsivité, de flexibilité mentale, de planification</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Rééducation &amp; soutien social</h4>\n      <ul>\n        <li><strong>Rééducation des troubles des apprentissages</strong> spécifiques fréquemment associés ;</li>\n        <li><strong>Associations de parents</strong> = partenaires indispensables (ex. <strong>Hypersupers</strong>).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Traitement <span class=\"kw-etio\">médicamenteux</span></h4>\n      <table >\n        <thead><tr><th>Item</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td>Enfant <span class=\"kw-chiffre\">≥ 6 ans</span> avec TDAH <strong>si <span class=\"kw-clinique\">les</span> mesures d’aménagement de l’environnement sont insuffisantes</strong> (traitement désormais introductible également chez l’adulte)</td>\n          </tr>\n          <tr>\n            <td><strong>Molécule</strong></td>\n            <td><span class=\"kw-ttt\">Méthylphénidate</span> — <span class=\"kw-ttt\">psychostimulant</span> dérivé des <span class=\"kw-ttt\">amphétamines</span>, formes LI <em>et</em> LP</td>\n          </tr>\n          <tr>\n            <td><strong>Efficacité</strong></td>\n            <td>Efficace pour <span class=\"kw-chiffre\">~80%</span> des patients</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Hiérarchie thérapeutique à retenir.</strong> <span class=\"kw-def\">1)</span> Aménagements scolaires + psychothérapie en <span class=\"kw-chiffre\">1ère intention</span> ; <span class=\"kw-def\">2)</span> Méthylphénidate <strong>uniquement si</strong> <span class=\"kw-clinique\">les</span> mesures non pharmacologiques sont insuffisantes, chez l’enfant <span class=\"kw-chiffre\">≥ 6 ans</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 68 — Troubles du comportement de l'ado · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 121 — Handicap psychique</em></p>","frequence":4}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"0ba556c8f3c8","n":67,"o":"67-1","u":"Diagnostic positif","t":"Connaître la définition et la sémiologie des troubles du spectre de l’autisme","q":"Quelle est la sémiologie du caractère restreint et répétitif des comportements, des intérêts et des activités dans le Trouble du Spectre de l'Autisme (TSA) ?","a":"Le caractère restreint et répétitif dans le TSA se manifeste par :<ul><li><strong>Comportements répétitifs et stéréotypés</strong> : <strong>stéréotypies motrices</strong> (mouvements répétitifs du tronc, de la tête, des membres supérieurs comme le <strong>flapping</strong>), utilisation répétitive des objets, <strong>stéréotypies verbales</strong> (écholalies, langage idiosyncrasique). Risque d'<strong>automutilation</strong>.</li><li><strong>Routines inflexibles et intolérance au changement</strong> : adhésion inflexible à des routines (même mineures), rituels verbaux ou non verbaux, <strong>détresse face à un changement</strong> (besoin d'immuabilité).</li><li><strong>Intérêts restreints et fixes</strong> : attachement idiosyncratique à des objets insolites, <strong>peurs inhabituelles</strong> au regard de l'âge, intérêts circonscrits et persévérants (par ex. chiffres, cartes de bus).</li><li><strong>Particularités sensorielles</strong> : <strong>hypo ou hyperréactivité</strong> à certaines stimulations sensorielles (indifférence à la douleur/température ou sensibilité excessive aux bruits), intérêt inhabituel pour des aspects sensoriels (comportements de flairage, fascination pour stimuli lumineux).</li></ul>"},{"i":"bec7fac96d93","n":67,"o":"67-1","u":"Diagnostic positif","t":"Connaître la définition et la sémiologie des troubles du spectre de l’autisme","q":"Quels sont les signes d'alerte du Trouble du Spectre de l'Autisme (TSA) à différentes tranches d'âge en petite enfance ?","a":"Les signes d'alerte du TSA varient selon l'âge :<ul><li><strong>0-6 mois</strong> : Nourrisson <strong>trop calme/indifférent</strong> ou trop agité, <strong>absence de sourire-réponse</strong>, pas de regard.</li><li><strong>6-12 mois</strong> : Activités stéréotypées verbales ou motrices, <strong>pas de peur de l'étranger</strong>, aréactivité au bruit, désintérêt pour l'environnement.</li><li><strong>12-24 mois</strong> : <strong>Retard de langage</strong> (environ 1/3 des enfants présentent une stagnation ou <strong>régression</strong> du développement socio-communicatif), retard global des acquisitions, automutilation, absence de jeu, comportements bizarres.</li></ul>"},{"i":"c2ce26003ca9","n":67,"o":"67-1","u":"Diagnostic positif","t":"Connaître la définition et la sémiologie des troubles du spectre de l’autisme","q":"Quelle est la sémiologie des anomalies de la communication et des interactions sociales dans le Trouble du Spectre de l'Autisme (TSA) ?","a":"Les anomalies de la communication et des interactions sociales dans le TSA incluent :<ul><li><strong>Déficit de réciprocité</strong> : absence ou rareté des <strong>sourires-réponses</strong>, pauvreté de l'<strong>attention conjointe</strong>, conversations centrées sur leurs propres intérêts, difficulté d'accès à l'implicite et au langage figuré (pragmatique du langage).</li><li><strong>Anomalie du contact</strong> : peu d'expressions faciales, gestuelle pauvre, contact oculaire absent/rare/fluctuant, ne fait pas de gestes sociaux comme « oui/non » ou « coucou/au revoir ». Rareté du <strong>pointage proto-impératif</strong> (pour obtenir) et <strong>proto-déclaratif</strong> (pour partager une information).</li><li><strong>Anomalie sociale</strong> : absence ou anomalie du jeu (pas de jeux sociaux réciproques, pas de faire-semblant), maladresse et isolement relationnel, peu d'intérêt pour les pairs.</li></ul>"},{"i":"c5e45d0789ee","n":67,"o":"67-1","u":"Diagnostic positif","t":"Connaître la définition et la sémiologie des troubles du spectre de l’autisme","q":"Quelle est la définition du Trouble du Spectre de l'Autisme (TSA) et ses principales manifestations psychopathologiques ?","a":"<p>Le Trouble du Spectre de l'Autisme (TSA) est un trouble d'origine <strong>neurodéveloppementale</strong>. Ses signes psychopathologiques principaux se manifestent par :</p><ul><li>Des <strong>perturbations dans l'interaction et la communication sociale</strong>.</li><li>Un <strong>caractère restreint et répétitif des comportements, des intérêts ou des activités</strong>.</li></ul>"},{"i":"10ea41525518","n":67,"o":"67-4","u":"Définition","t":"Connaître la définition et la sémiologie d’un trouble déficit de l’attention hyperactivité (TDAH)","q":"Quelles sont les manifestations sémiologiques du TDAH liées à l'hyperactivité ?","a":"<ul><li>Activité excessive, désordonnée, mal contrôlée, peu productive ni efficace (<strong>instabilité motrice</strong>).</li><li>Difficulté à rester assis, besoin de courir partout.</li><li>L'hyperactivité est présente dans quasiment tous les domaines de vie.</li><li>La personne est souvent décrite comme « <strong>une pile électrique</strong> », « <strong>montée sur ressort</strong> », « ne s’arrêtant jamais ».</li></ul>"},{"i":"41c20e98d86e","n":67,"o":"67-4","u":"Définition","t":"Connaître la définition et la sémiologie d’un trouble déficit de l’attention hyperactivité (TDAH)","q":"Quelle est la définition du Trouble Déficit de l'Attention avec ou sans Hyperactivité (TDAH) ?","a":"<p>Le <strong>TDAH</strong> se caractérise par une <strong>inattention</strong> et/ou une <strong>hyperactivité/impulsivité</strong> plus importantes que ce qui est attendu pour l’âge. Les symptômes débutent dans l’enfance, sont durables/persistants et entraînent un retentissement significatif.</p>"},{"i":"8d0159543506","n":67,"o":"67-4","u":"Définition","t":"Connaître la définition et la sémiologie d’un trouble déficit de l’attention hyperactivité (TDAH)","q":"Quelles sont les manifestations sémiologiques du TDAH liées à l'inattention ?","a":"<ul><li>Difficultés à se concentrer et à maintenir la concentration (fautes d’étourderie).</li><li><strong>Distractibilité</strong> par distracteurs internes (pensées) ou externes (stimuli).</li><li>Difficultés à comprendre et suivre règles et consignes.</li><li>Difficultés d’<strong>organisation</strong> liées à un défaut de planification et de mémoire de travail.</li><li>Oublis ou pertes d’objets.</li><li><strong>Procrastination</strong> systématique, lenteur d’exécution.</li><li>Évitement et manque de motivation pour les tâches demandant un effort cognitif durable.</li></ul>"},{"i":"8ee66b32b233","n":67,"o":"67-4","u":"Définition","t":"Connaître la définition et la sémiologie d’un trouble déficit de l’attention hyperactivité (TDAH)","q":"Quelles sont les manifestations sémiologiques du TDAH liées à l'impulsivité ?","a":"<ul><li>Faire ou dire quelque chose de façon impérieuse, sans pouvoir différer, sans anticiper les conséquences.</li><li><strong>Précipitation</strong> (répondre sans attendre la fin de la question).</li><li><strong>Prises de risques</strong> (ex. ne pas regarder avant de traverser).</li><li>Incapacité à attendre son tour (jeux, tours de parole).</li></ul>"},{"i":"97dd9f59328c","n":67,"o":"67-4","u":"Définition","t":"Connaître la définition et la sémiologie d’un trouble déficit de l’attention hyperactivité (TDAH)","q":"Quelle est l'évolution des manifestations du TDAH selon l'âge et le sexe ?","a":"<ul><li>L'<strong>hyperactivité motrice</strong> s’atténue avec l'âge ou change de forme (sensation intérieure d’impatience).</li><li>L'<strong>impulsivité et l'inattention</strong> restent souvent problématiques.</li><li>Le TDAH persiste à l’âge adulte avec un retentissement pour les <strong>2/3 des patients</strong>.</li><li>Chez la <strong>fille</strong>, l'<strong>inattention</strong> est souvent prédominante (parfois sans hyperactivité), ce qui peut entraîner un <strong>diagnostic tardif</strong>.</li></ul>"}]};